package com.robothygenism.platform.operations;

import com.robothygenism.platform.auth.PermissionService;import com.robothygenism.platform.auth.PlatformPrincipal;import com.robothygenism.platform.tenancy.ScopeService;
import java.util.Map;import java.util.UUID;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/v1") public class OperationsController{
 private final JdbcClient jdbc;private final PermissionService permissions;private final ScopeService scope;public OperationsController(JdbcClient j,PermissionService p,ScopeService s){jdbc=j;permissions=p;scope=s;}
 @GetMapping("/dashboard")public Map<String,Object> dashboard(Authentication a){var p=p(a);String filter=p.superAdmin()?"":" WHERE r.\"tenantId\"=:tenant";var robots=(p.superAdmin()?jdbc.sql("SELECT COUNT(*) total,COUNT(*) FILTER(WHERE \"onlineStatus\"='ONLINE') online,COUNT(*) FILTER(WHERE \"onlineStatus\"='OFFLINE') offline,COUNT(*) FILTER(WHERE \"operationalState\"='RUNNING') running,COUNT(*) FILTER(WHERE \"operationalState\"='FAULT') fault,COUNT(*) FILTER(WHERE \"operationalState\"='MAINTENANCE') maintenance,COUNT(*) FILTER(WHERE \"operationalState\"='CHARGING') charging FROM \"Robot\""):jdbc.sql("SELECT COUNT(*) total,COUNT(*) FILTER(WHERE \"onlineStatus\"='ONLINE') online,COUNT(*) FILTER(WHERE \"onlineStatus\"='OFFLINE') offline,COUNT(*) FILTER(WHERE \"operationalState\"='RUNNING') running,COUNT(*) FILTER(WHERE \"operationalState\"='FAULT') fault,COUNT(*) FILTER(WHERE \"operationalState\"='MAINTENANCE') maintenance,COUNT(*) FILTER(WHERE \"operationalState\"='CHARGING') charging FROM \"Robot\" r WHERE r.\"tenantId\"=:tenant").param("tenant",p.tenantId())).query().singleRow();var tasks=(p.superAdmin()?jdbc.sql("SELECT status::text status,COUNT(*) count FROM \"Task\" WHERE \"createdAt\">=CURRENT_DATE GROUP BY status"):jdbc.sql("SELECT status::text status,COUNT(*) count FROM \"Task\" WHERE \"tenantId\"=:tenant AND \"createdAt\">=CURRENT_DATE GROUP BY status").param("tenant",p.tenantId())).query().listOfRows();return Map.of("robots",robots,"todayTasks",tasks,"cleaning",Map.of("status","NOT_AVAILABLE"),"criticalFaults",jdbc.sql("SELECT id,\"robotId\",\"safeCode\",\"startAt\",latched,\"taskId\" FROM \"FaultEvent\" WHERE \"endAt\" IS NULL AND (latched=true OR \"fullBlock\"=true) ORDER BY \"startAt\" DESC LIMIT 10").query().listOfRows());}
 @GetMapping("/maintenance")public Map<String,Object> maintenance(Authentication a){return page(scoped("MaintenanceRecord",p(a),"enteredAt"));}
 @PostMapping("/maintenance")public Map<String,Object> maintenanceCreate(@RequestBody Maintenance r,Authentication a){var p=p(a);permissions.require(p,"MAINTENANCE_MANAGE");scope.project(p,r.projectId());UUID id=UUID.randomUUID(),tenant=jdbc.sql("SELECT \"tenantId\" FROM \"Project\" WHERE id=:id").param("id",r.projectId()).query(UUID.class).single();jdbc.sql("INSERT INTO \"MaintenanceRecord\" (id,\"tenantId\",\"projectId\",\"robotId\",\"enteredAt\",reason,\"operatorId\",\"safeCodes\",\"createdAt\",\"updatedAt\") VALUES (:id,:tenant,:project,:robot,CURRENT_TIMESTAMP,:reason,:user,:codes,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)").param("id",id).param("tenant",tenant).param("project",r.projectId()).param("robot",r.robotId()).param("reason",r.reason()).param("user",p.id()).param("codes",r.safeCodes().toArray(String[]::new)).update();jdbc.sql("UPDATE \"Robot\" SET \"operationalState\"='MAINTENANCE' WHERE id=:id").param("id",r.robotId()).update();return Map.of("id",id,"status","ACTIVE");}
 @GetMapping("/reports")public Map<String,Object> reports(Authentication a){var p=p(a);var completion=(p.superAdmin()?jdbc.sql("SELECT COUNT(*) FILTER(WHERE status='COMPLETED') completed,COUNT(*) FILTER(WHERE status='FAILED') failed,COUNT(*) total FROM \"Task\""):jdbc.sql("SELECT COUNT(*) FILTER(WHERE status='COMPLETED') completed,COUNT(*) FILTER(WHERE status='FAILED') failed,COUNT(*) total FROM \"Task\" WHERE \"tenantId\"=:tenant").param("tenant",p.tenantId())).query().singleRow();return Map.of("tasks",completion,"cleaningArea",Map.of("status","NOT_AVAILABLE"),"utilization",Map.of("status","NOT_AVAILABLE"),"safeStatistics",jdbc.sql("SELECT \"safeCode\",COUNT(*) count FROM \"FaultEvent\" GROUP BY \"safeCode\" ORDER BY count DESC").query().listOfRows());}
 @GetMapping("/commands")public Map<String,Object> commands(Authentication a){return page(scoped("Command",p(a),"createdAt"));}
 @GetMapping("/audit-logs")public Map<String,Object> audit(Authentication a){var p=p(a);permissions.require(p,"AUDIT_READ");return page(scoped("AuditLog",p,"createdAt"));}
 private java.util.List<Map<String,Object>> scoped(String table,PlatformPrincipal p,String order){if(p.superAdmin())return jdbc.sql("SELECT * FROM \""+table+"\" ORDER BY \""+order+"\" DESC LIMIT 500").query().listOfRows();return jdbc.sql("SELECT * FROM \""+table+"\" WHERE \"tenantId\"=:tenant ORDER BY \""+order+"\" DESC LIMIT 500").param("tenant",p.tenantId()).query().listOfRows();}private Map<String,Object>page(java.util.List<Map<String,Object>>r){return Map.of("items",r,"total",r.size(),"page",1,"pageSize",r.size());}private PlatformPrincipal p(Authentication a){return(PlatformPrincipal)a.getPrincipal();}
 public record Maintenance(UUID projectId,UUID robotId,String reason,java.util.List<String>safeCodes){}
}



